def close_from_row(line):
    parts = line.split(",")
    return float(parts[1])

print(close_from_row("Tue,102.50\n"))

with open("prices.csv", "w") as f:
    f.write("Day,Close\nMon,101.20\nTue,102.50\nWed,99.80\nThu,100.40\nFri,101.10\n")

def last_close(name):
    lines = open(name).readlines()
    return float(lines[-1].split(",")[1])

print(f"Last close: £{last_close('prices.csv'):.2f}")
